import six
from .entrypoint import EntryPoint
from .prisma import Prisma
from .lsu import LSU
from .airmosaic import Airmosaic, AirmosaicWA
from .tstm import Tstm
from abc import ABCMeta, abstractmethod


@six.add_metaclass(ABCMeta)
class BaseFactory:

    def __init__(self):
        self._entry_point = EntryPoint()

    @abstractmethod
    def create(self, config):
        pass


class PrismaFactory(BaseFactory):

    def __init__(self):
        BaseFactory.__init__(self)

    def create(self, config):
        node_dict = {}
        for node_name, node_config in config.prisma.components.items():
            node_factory = self._entry_point.get_factory_instance(node_config.type)
            node_dict[node_name] = node_factory.create(node_config)
        return Prisma(config, node_dict)


class LSUFactory(BaseFactory):

    def __init__(self):
        BaseFactory.__init__(self)

    def create(self, config):
        executor_factory = self._entry_point.get_factory_instance(config.executor.type)
        return LSU(config, executor_factory.create(config.executor))


class AirmosaicFactory(BaseFactory):

    def __init__(self):
        BaseFactory.__init__(self)

    def create(self, config):
        executor_factory = self._entry_point.get_factory_instance(config.executor.type)
        return Airmosaic(config, executor_factory.create(config.executor))


class AirmosaicWAFactory(BaseFactory):

    def __init__(self):
        BaseFactory.__init__(self)

    def create(self, config):
        executor_factory = self._entry_point.get_factory_instance(config.executor.type)
        return AirmosaicWA(config, executor_factory.create(config.executor))


class TstmFactory(BaseFactory):

    def __init__(self):
        BaseFactory.__init__(self)

    def create(self, config):
        executor_factory = self._entry_point.get_factory_instance(config.executor.type)
        return Tstm(config, executor_factory.create(config.executor))
